/* ================================================================
   LANDSCAPE CHARTS — stacked bar (top) + grouped bar (bottom)
   ================================================================
   Both charts update together when an institution button is clicked.

   TOP:    #landscape-chart-stacked
           100% stacked horizontal bar — 1 row showing discipline
           share for the selected institution (or ALL combined).

   BOTTOM: #landscape-chart-grouped
           Grouped horizontal bar — Citing vs Cited absolute counts
           for the same institution.

   EDITING:
   - Colours:           DISCIPLINE_COLORS (Plotly default palette)
   - Institution order: INSTITUTION_ORDER
   - Discipline order:  DISCIPLINE_ORDER
   - Bar colours for grouped chart: GROUPED_COLOR_CITING / _CITED
   ================================================================ */

/* ----------------------------------------------------------------
   DISCIPLINE_COLORS — Plotly default 11-colour palette
   ---------------------------------------------------------------- */
var DISCIPLINE_COLORS = {
    "Science": 0x636EFA,
    "Medicine": 0xEF553B,
    "Geo./Anthrop.": 0x00CC96,
    "Technology": 0xAB63FA,
    "Agriculture": 0xFFA15A,
    "Social Sciences": 0x19D3F3,
    "Education": 0xFF6692,
    "Political Science": 0xB6E880,
    "Phil./Psych./Rel.": 0xFF97FF,
    "Multidisciplinary": 0xFECB52,
    "Others": 0x888888
};

/* ----------------------------------------------------------------
   INSTITUTION_ORDER — order of institutions in ALL-view stacked bar
   ---------------------------------------------------------------- */
var INSTITUTION_ORDER = ["UNIBO", "UNIMI", "UNIPD", "UNITO", "UPO", "SNS"];

/* ----------------------------------------------------------------
   DISCIPLINE_ORDER — left-to-right segment order within each bar
   ---------------------------------------------------------------- */
var DISCIPLINE_ORDER = [
    "Science", "Medicine", "Geo./Anthrop.", "Technology",
    "Agriculture", "Social Sciences", "Education",
    "Political Science", "Phil./Psych./Rel.", "Multidisciplinary", "Others"
];

/* ----------------------------------------------------------------
   GROUPED CHART COLOURS — Citing / Cited bar colours
   Edit these two hex values to restyle the grouped bar chart.
   ---------------------------------------------------------------- */
var GROUPED_COLOR_CITING = 0x636EFA;   /* blue-purple */
var GROUPED_COLOR_CITED = 0xEF553B;   /* orange-red  */

/* Legend labels for grouped chart */
var LABEL_CITING = "Citing";
var LABEL_CITED = "Cited";


/* ================================================================
   STATE
   ================================================================ */
var stackedRoot = null;
var groupedRoot = null;
var currentInst = "ALL";


/* ================================================================
   SHARED TOOLTIP HELPER
   ================================================================ */
function makeTT(root, accentHex) {
    var tt = am5.Tooltip.new(root, {
        pointerOrientation: "horizontal",
        getFillFromSprite: false,
        autoTextColor: false
    });
    tt.get("background").setAll({
        fill: am5.color(0x1e0e2e), fillOpacity: 0.95,
        stroke: am5.color(accentHex || 0x888888),
        strokeOpacity: 0.5, strokeWidth: 1,
        cornerRadiusBL: 5, cornerRadiusBR: 5,
        cornerRadiusTL: 5, cornerRadiusTR: 5
    });
    tt.label.setAll({ fill: am5.color(0xFFFFFF), fontSize: 12, lineHeight: 1.6 });
    return tt;
}


/* ================================================================
   TOP CHART — 100% stacked bar
   When instKey === "ALL": one bar per institution (6 bars).
   When instKey is a specific institution: one bar total.
   ================================================================ */
function renderStackedChart(instKey) {

    if (stackedRoot) { stackedRoot.dispose(); stackedRoot = null; }

    /* Build chartData ------------------------------------------- */
    /* Always 1 bar — use the selected institution or ALL aggregate */
    var keys = [instKey];

    var chartData = keys.map(function (key) {
        var instData = LANDSCAPE_DATA[key];
        var row = { institution: key === "ALL" ? "All institutions" : key };
        var total = 0, sums = {};
        DISCIPLINE_ORDER.forEach(function (disc) {
            var d = instData && instData.disciplines.find(function (x) { return x.name === disc; });
            var v = d ? (d.citing + d.cited) : 0;
            sums[disc] = v; total += v;
        });
        DISCIPLINE_ORDER.forEach(function (disc) {
            row[disc] = total > 0 ? parseFloat(((sums[disc] / total) * 100).toFixed(2)) : 0;
        });
        return row;
    });

    stackedRoot = am5.Root.new("landscape-chart-stacked");
    stackedRoot.setThemes([am5themes_Animated.new(stackedRoot)]);

    var chart = stackedRoot.container.children.push(
        am5xy.XYChart.new(stackedRoot, {
            panX: false, panY: false,
            wheelX: "none", wheelY: "none",
            layout: stackedRoot.verticalLayout
        })
    );

    /* Y-axis */
    var yRenderer = am5xy.AxisRendererY.new(stackedRoot, { inversed: true });
    yRenderer.labels.template.setAll({
        fontSize: 12, fontWeight: "600",
        fill: am5.color(0xDDDDDD), paddingRight: 10
    });
    yRenderer.grid.template.set("visible", false);
    var yAxis = chart.yAxes.push(
        am5xy.CategoryAxis.new(stackedRoot, {
            categoryField: "institution", renderer: yRenderer
        })
    );
    yAxis.data.setAll(chartData);

    /* X-axis */
    var xRenderer = am5xy.AxisRendererX.new(stackedRoot, {});
    xRenderer.labels.template.setAll({ fontSize: 10, fill: am5.color(0x888888), text: "{value}%" });
    xRenderer.grid.template.setAll({ stroke: am5.color(0xFFFFFF), strokeOpacity: 0.05 });
    var xAxis = chart.xAxes.push(
        am5xy.ValueAxis.new(stackedRoot, {
            min: 0, max: 100, strictMinMax: true, renderer: xRenderer
        })
    );

    /* Series — one per discipline */
    DISCIPLINE_ORDER.forEach(function (disc, i) {
        var col = DISCIPLINE_COLORS[disc] || 0x888888;
        var isFirst = (i === 0);
        var isLast = (i === DISCIPLINE_ORDER.length - 1);

        var series = chart.series.push(
            am5xy.ColumnSeries.new(stackedRoot, {
                name: disc,
                xAxis: xAxis, yAxis: yAxis,
                valueXField: disc,
                categoryYField: "institution",
                stacked: true,
                tooltip: makeTT(stackedRoot, col)
            })
        );
        /* TOOLTIP TEXT */
        series.set("tooltipText", "{name}  {valueX.formatNumber('#.1')}%");

        series.columns.template.setAll({
            /* BAR HEIGHT — single thin bar, same for ALL and per-institution.
               Increase am5.percent value to make thicker.               */
            height: am5.percent(28),
            fill: am5.color(col),
            stroke: am5.color(0xFFFFFF),
            strokeWidth: 1,
            strokeOpacity: 0.18,
            cornerRadiusTL: isFirst ? 4 : 0,
            cornerRadiusBL: isFirst ? 4 : 0,
            cornerRadiusTR: isLast ? 4 : 0,
            cornerRadiusBR: isLast ? 4 : 0
        });
        series.columns.template.states.create("hover", {
            fillOpacity: 1, strokeOpacity: 0.5
        });

        series.data.setAll(chartData);
        series.appear(500 + i * 20);
    });

    /* Legend — always shown */
    var legend = chart.children.push(
        am5.Legend.new(stackedRoot, {
            centerX: am5.percent(0), x: am5.percent(0),
            marginTop: 10, useDefaultMarker: true
        })
    );
    legend.labels.template.setAll({ fontSize: 10, fill: am5.color(0xAAAAAA) });
    legend.markers.template.setAll({ width: 9, height: 9 });
    legend.data.setAll(chart.series.values);

    chart.appear(600, 100);

} /* end renderStackedChart */


/* ================================================================
   BOTTOM CHART — grouped bar (Citing vs Cited)
   When instKey === "ALL": uses the ALL aggregated data.
   When instKey is specific: uses that institution's data.
   ================================================================ */
function renderGroupedChart(instKey) {

    if (groupedRoot) { groupedRoot.dispose(); groupedRoot = null; }

    var instData = LANDSCAPE_DATA[instKey];
    if (!instData) return;

    /* Sort by combined volume descending */
    var sorted = instData.disciplines.slice().sort(function (a, b) {
        return (b.citing + b.cited) - (a.citing + a.cited);
    });
    var chartData = sorted.map(function (d) {
        return { discipline: d.name, citing: d.citing, cited: d.cited };
    });

    groupedRoot = am5.Root.new("landscape-chart-grouped");
    groupedRoot.setThemes([am5themes_Animated.new(groupedRoot)]);

    var chart = groupedRoot.container.children.push(
        am5xy.XYChart.new(groupedRoot, {
            panX: false, panY: false,
            wheelX: "none", wheelY: "none",
            layout: groupedRoot.verticalLayout
        })
    );

    /* Y-axis */
    var yRenderer = am5xy.AxisRendererY.new(groupedRoot, {
        minGridDistance: 8, inversed: true
    });
    yRenderer.labels.template.setAll({
        fontSize: 12, fill: am5.color(0xDDDDDD),
        maxWidth: 145, oversizedBehavior: "wrap"
    });
    yRenderer.grid.template.set("visible", false);
    var yAxis = chart.yAxes.push(
        am5xy.CategoryAxis.new(groupedRoot, {
            categoryField: "discipline", renderer: yRenderer
        })
    );
    yAxis.data.setAll(chartData);

    /* X-axis */
    var xRenderer = am5xy.AxisRendererX.new(groupedRoot, {});
    xRenderer.labels.template.setAll({ fontSize: 10, fill: am5.color(0x888888) });
    xRenderer.grid.template.setAll({ stroke: am5.color(0xFFFFFF), strokeOpacity: 0.05 });
    var xAxis = chart.xAxes.push(
        am5xy.ValueAxis.new(groupedRoot, { min: 0, renderer: xRenderer })
    );

    /* Helper: one grouped series */
    function makeGrouped(field, colorHex, label) {
        var series = chart.series.push(
            am5xy.ColumnSeries.new(groupedRoot, {
                name: label,
                xAxis: xAxis, yAxis: yAxis,
                valueXField: field,
                categoryYField: "discipline",
                clustered: true,
                tooltip: makeTT(groupedRoot, colorHex)
            })
        );
        series.set("tooltipText", "{name}  {categoryY}: {valueX.formatNumber('#,###')}");
        series.columns.template.setAll({
            height: am5.percent(60),
            cornerRadiusTR: 3, cornerRadiusBR: 3,
            fill: am5.color(colorHex), stroke: am5.color(colorHex),
            fillOpacity: 0.85
        });
        series.columns.template.states.create("hover", { fillOpacity: 1 });
        series.data.setAll(chartData);
        series.appear(600);
        return series;
    }

    /* GROUPED BAR COLOURS — edit GROUPED_COLOR_CITING / _CITED above */
    makeGrouped("citing", GROUPED_COLOR_CITING, LABEL_CITING);
    makeGrouped("cited", GROUPED_COLOR_CITED, LABEL_CITED);

    /* Legend */
    var legend = chart.children.push(
        am5.Legend.new(groupedRoot, {
            centerX: am5.percent(0), x: am5.percent(0), marginTop: 10
        })
    );
    legend.labels.template.setAll({ fontSize: 11, fill: am5.color(0xAAAAAA) });
    legend.data.setAll(chart.series.values);

    chart.appear(600, 100);

} /* end renderGroupedChart */


/* ================================================================
   SWITCH — update both charts for a given institution key
   ================================================================ */
function switchInstitution(instKey) {
    currentInst = instKey;
    renderStackedChart(instKey);
    renderGroupedChart(instKey);
}


/* ================================================================
   PAGE INITIALISATION
   ================================================================ */
document.addEventListener('DOMContentLoaded', function () {

    /* Render both charts with ALL on load */
    switchInstitution("ALL");

    /* Institution button clicks */
    document.querySelectorAll('.landscape-inst-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            document.querySelectorAll('.landscape-inst-btn').forEach(function (b) {
                b.classList.remove('active');
            });
            this.classList.add('active');
            switchInstitution(this.dataset.inst);
        });
    });

});


