/* ----------------------------------------------------------------
   renderSunburst(instKey)
   Uses Plotly.react for smooth institution switching
   ---------------------------------------------------------------- */
var _sbInit = false;

function renderSunburst(instKey) {
    var el = document.getElementById('sunburst-chart');
    if (!el) return;

    var d = PLOTLY_SB.traces[instKey];
    if (!d) return;

    var trace = {
        type: 'sunburst',
        ids: d.ids,
        labels: d.labels,
        parents: d.parents,
        values: d.values,
        customdata: d.customdata,
        /* HOVER TEMPLATE — edit here to change hover text format */
        hovertemplate: '%{customdata}<extra></extra>',
        branchvalues: 'remainder',
        /* START ANGLE — 90 = 12 o'clock */
        rotation: 90,
        sort: false,
        insidetextorientation: 'radial',
        /* HOLE SIZE — 0 to 1. Smaller = smaller hole */
        hole: 0.12,
        leaf: { opacity: 0.78 },
        marker: {
            colors: d.colors,
            line: { width: 1, color: 'white' }
        },
        maxdepth: 2,
        /* Centre text — shown in the hole */
        title: {
            text: '<b>' + (instKey === 'ALL' ? 'All' : instKey) + '</b>',
            font: {
                size: 14,
                color: '#320E3B',
                family: 'Playfair Display, serif'
            },
            position: 'middle center'
        }
    };

    var layout = {
        margin: { t: 0, l: 0, r: 0, b: 0 },
        paper_bgcolor: 'rgba(0,0,0,0)',
        plot_bgcolor: 'rgba(0,0,0,0)',
        showlegend: false
    };

    var config = {
        responsive: true,
        displayModeBar: false
    };

    if (_sbInit) {
        Plotly.react(el, [trace], layout, config);
    } else {
        Plotly.newPlot(el, [trace], layout, config);
        _sbInit = true;

        /* Click → update info panel */
        el.on('plotly_click', function (eventData) {
            if (!eventData || !eventData.points) return;
            var pt = eventData.points[0];
            var infoEl = document.getElementById('sunburst-info');
            if (!infoEl || !pt.customdata) return;
            infoEl.innerHTML =
                '<p class="sunburst-info-stat" style="font-size:0.85rem;color:#444;line-height:1.7">' +
                pt.customdata + '</p>';
        });

        /* Hover → update info panel */
        el.on('plotly_hover', function (eventData) {
            if (!eventData || !eventData.points) return;
            var pt = eventData.points[0];
            var infoEl = document.getElementById('sunburst-info');
            if (!infoEl || !pt.customdata) return;
            infoEl.innerHTML =
                '<p class="sunburst-info-stat" style="font-size:0.85rem;color:#444;line-height:1.7">' +
                pt.customdata + '</p>';
        });
    }
}


/* ----------------------------------------------------------------
   Init: render when section scrolls into view
   ---------------------------------------------------------------- */
document.addEventListener('DOMContentLoaded', function () {

    var sunburstSection = document.querySelector('.rq2-sunburst-section');
    var rendered = false;

    function initSunburst() {
        if (!rendered) {
            rendered = true;
            setTimeout(function () { renderSunburst('ALL'); }, 200);
        }
    }

    if (sunburstSection && 'IntersectionObserver' in window) {
        var obs = new IntersectionObserver(function (entries) {
            if (entries[0].isIntersecting) {
                initSunburst();
                obs.unobserve(sunburstSection);
            }
        }, { threshold: 0.05 });
        obs.observe(sunburstSection);
    } else {
        setTimeout(initSunburst, 800);
    }

    /* Institution buttons */
    document.querySelectorAll('.sunburst-inst-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            document.querySelectorAll('.sunburst-inst-btn').forEach(function (b) {
                b.classList.remove('active');
            });
            this.classList.add('active');
            renderSunburst(this.dataset.sunburst);
        });
    });

});


