    var citedFilter = citedEl ? getMultiSelectValues(citedEl) : ['All'];

    var links = base.links.filter(function (l) {
        var citingOk = citingFilter[0] === 'All' || citingFilter.indexOf(l.c) >= 0;
        var citedOk = citedFilter[0] === 'All' || citedFilter.indexOf(l.d) >= 0;
        return citingOk && citedOk;
    });

    /* Determine which node indices are actually used */
    var usedNodes = new Set();
    links.forEach(function (l) { usedNodes.add(l.s); usedNodes.add(l.t); });

